// Dedup returns a new slice with duplicates removed, preserving first-seen
// order. It is O(n^2) in the worst case.
func Dedup(in []int) []int {
	out := make([]int, 0, len(in))
	for _, v := range in {
		if contains(out, v) {
			continue
		}
		out = append(out, v)
	}
	return out
}

func contains(out []int, v int) bool {
	for _, v2 := range out {
		if v2 == v {
			return true
		}
	}
	return false
}

