// Balanced reports whether s contains balanced and nested brackets. Other
// characters are ignored.
func Balanced(s string) bool {
	var stack []byte
	for _, b := range s {
		switch b {
		case '(', '[', '{':
			stack = append(stack, b)
		case ')':
			if len(stack) == 0 || stack[len(stack)-1] != '(' {
				return false
			}
			stack = stack[:len(stack)-1]
		case ']':
			if len(stack) == 0 || stack[len(stack)-1] != '[' {
				return false
			}
			stack = stack[:len(stack)-1]
		case '}':
			if len(stack) == 0 || stack[len(stack)-1] != '{' {
				return false
			}
			stack = stack[:len(stack)-1]
		}
	}
	return len(stack) == 0
}

