// Merge collapses overlapping closed intervals into the smallest number of
// non-overlapping intervals. The result is sorted by start.
func Merge(in [][2]int) [][2]int {
	if len(in) <= 1 {
		return in
	}
	out := make([][2]int, 0, len(in))
	sort.Slice(in, func(i, j int) bool { return in[i][0] < in[j][0] })
	start, end := in[0][0], in[0][1]
	for i := 1; i <= len(in); i++ {
		if i < len(in) && in[i][0] <= end {
			end = max(end, in[i][1])
			continue
		}
		out = append(out, [2]int{start, end})
		if i < len(in) {
			start, end = in[i][0], in[i][1]
		}
	}
	return out
}

