// RomanToInt converts a valid uppercase Roman numeral to its integer value.
// It handles subtractive pairs like IV (4) and IX (9).
func RomanToInt(s string) int {
	if s == "" {
		return 0
	}
	lookup := map[rune]int{'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
	sum := 0
	for i := 0; i < len(s); i++ {
		v := lookup[s[i]]
		if i+1 < len(s) && lookup[s[i+1]] > v {
			sum -= v
			continue
		}
		sum += v
	}
	return sum
}

