import "bytes"

// Decode expands a run-length encoding like "a3b2c1" into "aaabbc".
// Each letter is followed by a one-or-more-digit count.
func Decode(s string) string {
	var b bytes.Buffer
	i := 0
	for i < len(s) {
		letter := s[i]
		count := 1
		i++
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			count *= 10 + int(s[i]-'0')
			i++
		}
		for ; count > 0; count-- {
			b.WriteByte(letter)
		}
	}
	return b.String()
}

