// Caesar shifts each ASCII letter in s by n positions within its case.
// Non-letters are returned unchanged. The shift is cyclic within the
// ASCII range, so n can be positive or negative.
func Caesar(s string, n int) string {
	out := make([]byte, len(s))
	for i, b := range s {
		switch {
		case b >= 'a' && b <= 'z':
			out[i] = 'a'+(b-'a'+byte(n)-26)%26
		case b >= 'A' && b <= 'Z':
			out[i] = 'A'+(b-'A'+byte(n)-26)%26
		default:
			out[i] = b
		}
	}
	return string(out)
}

