import "sort"

// TopK returns the k most frequent whitespace-separated words, most frequent
// first, ties broken alphabetically. It returns at most k elements.
func TopK(s string, k int) []string {
	counts := make(map[string]int)
	for _, w := range s.Fields() {
		counts[w]++
	}
	type pair struct {
		word  string
		count int
	}
	pairs := make([]pair, 0, len(counts))
	for w, c := range counts {
		pairs = append(pairs, pair{w, c})
	}
	sort.Slice(pairs, func(i, j int) bool {
		if pairs[i].count != pairs[j].count {
			return pairs[i].count > pairs[j].count
		}
		return pairs[i].word < pairs[j].word
	})
	if k > len(pairs) {
		k = len(pairs)
	}
	out := make([]string, k)
	for i := 0; i < k; i++ {
		out[i] = pairs[i].word
	}
	return out
}

