// CamelToSnake converts camelCase to snake_case (an underscore before each
// upper-case letter, lower-cased). It returns the empty string for empty
// input.
func CamelToSnake(s string) string {
	if s == "" {
		return ""
	}
	var buf bytes.Buffer
	buf.WriteByte(s[0])
	for i := 1; i < len(s); i++ {
		if s[i] >= 'A' && s[i] <= 'Z' {
			buf.WriteByte('_')
		}
		buf.WriteByte(s[i])
	}
	return buf.String()
}

