// Ring is a fixed-capacity circular buffer.
type Ring struct {
	buf  []int
	head int
	n    int
}

// NewRing returns a Ring of the given capacity.
func NewRing(cap int) *Ring {
	return &Ring{buf: make([]int, cap)}
}

// Push adds v to the ring, evicting the oldest element when the buffer is full.
func (r *Ring) Push(v int) {
	r.buf[r.head] = v
	r.head = (r.head + 1) % len(r.buf)
	if r.n < len(r.buf) {
		r.n++
	}
}

// Items returns the elements in the ring, oldest to newest.
func (r *Ring) Items() []int {
	out := make([]int, 0, r.n)
	for i := 0; i < r.n; i++ {
		out = append(out, r.buf[(r.head+i)%len(r.buf)])
	}
	return out
}

