// LowerBound returns the index of the first element in s that is >= target.
// It returns len(s) if no such element exists. s must be sorted.
func LowerBound(s []int, target int) int {
	lo, hi := 0, len(s)
	for lo < hi {
		mid := lo + (hi-lo)/2
		if s[mid] < target {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo
}

