// Rotate rotates m 90 degrees clockwise in place. It modifies the input
// matrix, so the original is lost. The result is a new matrix.
func Rotate(m [][]int) {
	n := len(m)
	for i := 0; i < n/2; i++ {
		for j := i; j < n-i-1; j++ {
			// save top
			top := m[i][j]
			// move left to top
			m[i][j] = m[n-j-1][i]
			// move bottom to left
			m[n-j-1][i] = m[n-i-1][n-j-1]
			// move right to bottom
			m[n-i-1][n-j-1] = m[j][n-i-1]
			// restore top
			m[j][n-i-1] = top
		}
	}
}

