// ParallelSum sums nums using exactly workers goroutines. The jobs channel
// is closed by the caller.
func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int, len(nums))
	for i := range nums {
		jobs <- nums[i]
	}
	close(jobs)

	sum := 0
	results := make(chan int, workers)
	for i := 0; i < workers; i++ {
		go func() {
			sum := 0
			for n := range jobs {
				sum += n
			}
			results <- sum
		}()
	}

	for i := 0; i < workers; i++ {
		sum += <-results
	}
	return sum
}

