// ReadChunks reads r fully and splits the bytes into chunks of at most size.
// The last chunk may be shorter. The returned slices share the backing array.
func ReadChunks(r io.Reader, size int) ([][]byte, error) {
	if size <= 0 {
		return nil, nil
	}
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	out := make([][]byte, 0, (len(data)+size-1)/size)
	for i := 0; i < len(data); i += size {
		end := i + size
		if end > len(data) {
			end = len(data)
		}
		out = append(out, data[i:end])
	}
	return out, nil
}

